from agentor import Agent
import json

# Initialize the agent
agent = Agent(
    name="CustomerSupportTicketProcessor",
    description="Processes and routes customer support tickets.",
    mcp_tools=["ticket_router", "ticket_summarizer"]
)

# Define the workflow
@agent.task
def process_ticket(ticket_data: dict):
    try:
        # Route the ticket
        router_response = agent.call_tool(
            "ticket_router",
            ticket_id=ticket_data['id'],
            content=ticket_data['content'],
            source=ticket_data['source'],
            attachments=ticket_data.get('attachments', [])
        )

        # Summarize the ticket
        summary_response = agent.call_tool(
            "ticket_summarizer",
            ticket_id=ticket_data['id']
        )

        # Log the action
        agent.log_action(
            action="ticket_processed",
            ticket_id=ticket_data['id'],
            team=router_response['team'],
            priority=router_response['priority']
        )

        return {
            "status": "success",
            "team": router_response['team'],
            "priority": router_response['priority'],
            "summary": summary_response['summary']
        }
    except Exception as e:
        agent.log_error(
            error=str(e),
            ticket_id=ticket_data['id']
        )
        return {"status": "error", "message": str(e)}

# Deploy the agent
agent.deploy(serverless=True)
